-- 商品图片
UPDATE `product` SET `image` = CASE `id`
  WHEN 1 THEN "https://images.unsplash.com/photo-1565708097881-bbf061e260e0?w=400"
  WHEN 2 THEN "https://images.unsplash.com/photo-1578874109531-ee2b1d3c19b0?w=400"
  WHEN 3 THEN "https://images.unsplash.com/photo-1601758228041-f3b2795255f1?w=400"
  WHEN 4 THEN "https://images.unsplash.com/photo-1583337130417-3346c1be7b0e?w=400"
  WHEN 5 THEN "https://images.unsplash.com/photo-1583336663277-620dc20b3e3c?w=400"
  WHEN 6 THEN "https://images.unsplash.com/photo-1576201836106-db1758fd1c97?w=400"
  ELSE `image`
END WHERE `id` BETWEEN 1 AND 6;

